#pragma once

#include <stdint.h>

/* Retail map tables (s_MapPoint2d, s_SpawnInfo, s_EventData), generated by tools/gen_map_data.py.
 * Positions are PS1 world meters (Y down); 3DS = (x, -y, -z), yaw_3ds = -yaw. */

typedef struct ShMapPoint {
    float x, z;
    uint8_t paper_map;      /* e_PaperMapIdx */
    uint8_t field_4_5;
    uint8_t loading_screen; /* e_LoadingScreenId */
    uint8_t param0;         /* usually Q8 angle (256 = 360 deg) */
    uint8_t param1;
} ShMapPoint;

typedef struct ShMapSpawn {
    float x, z;
    float yaw_deg;
    int16_t chara_id;      /* e_CharaId */
    uint8_t group;         /* index into the map's charaGroupIds */
    int8_t flags;          /* e_SpawnFlags (initial stateStep) */
    int8_t difficulty_min; /* e_GameDifficulty */
} ShMapSpawn;

typedef struct ShMapEvent {
    int16_t required_flag; /* must be set (0 = none) */
    int16_t complete_flag; /* set on completion; event skipped once set */
    int8_t trigger_type;   /* e_TriggerType */
    uint8_t activation_type;
    uint8_t point_idx;     /* into the map's ShMapPoint table */
    uint8_t required_item;
    uint8_t sys_state;     /* e_SysState */
    uint8_t event_param;   /* map msg / sfx / mapEventFuncs idx / map point */
    uint8_t transition_flags;
    uint8_t sfx_pair;
    uint8_t on_rail;
    uint8_t map_idx;
} ShMapEvent;

/* e_TriggerType / e_TriggerActivationType / e_SysState (subset) */
#define SH_TRIG_TICK 0
#define SH_TRIG_TOUCH_AABB 1
#define SH_TRIG_TOUCH_FACING 2
#define SH_TRIG_TOUCH_OBB_FACING 3
#define SH_TRIG_TOUCH_OBB 4
#define SH_ACT_NONE 0
#define SH_ACT_EXCLUSIVE 1
#define SH_ACT_BUTTON 2
#define SH_ACT_ITEM 3
#define SH_SYS_LOAD_OVERLAY 5
#define SH_SYS_LOAD_ROOM 6
#define SH_SYS_READ_MESSAGE 7
#define SH_SYS_EVENT_CALLBACK 10
#define SH_SYS_EVENT_SET_FLAG 11

/* e_CommonPickupItemId */
#define SH_PICKUP_FIRST_AID 0
#define SH_PICKUP_HEALTH_DRINK 1
#define SH_PICKUP_AMPOULE 2
#define SH_PICKUP_HANDGUN_BULLETS 3
#define SH_PICKUP_RIFLE_SHELLS 4
#define SH_PICKUP_SHOTGUN_SHELLS 5

typedef struct ShMapCommonPickup {
    uint16_t point_idx;
    uint8_t pickup_type; /* SH_PICKUP_* */
    int16_t event_flag;
} ShMapCommonPickup;
